//  distilled 标题在 OV 中已有等价正文时记 done（避免 write:0 重复导入死循环）
import fs from "fs";
import path from "path";
import os from "os";
import { spawnSync } from "child_process";

const BASE = "C:\\Users\\Administrator\\Documents\\deepseek-harness\\default-workspace\\memory-migration";
const REPORT = path.join(BASE, "out", "align-report.json");
const SRC_ROOT = path.join(BASE, "out", "distilled-projects");
const MEM = path.join(os.homedir(), ".openviking/data/viking/default/user/default/memories");

function loadMem(project, title) {
  const dir = path.join(SRC_ROOT, project);
  for (const f of fs.readdirSync(dir).filter((x) => x.endsWith(".json"))) {
    for (const m of JSON.parse(fs.readFileSync(path.join(dir, f), "utf8")).memories || []) {
      if (m.title === title) return m;
    }
  }
  return null;
}

function allBodies() {
  const parts = [];
  function walk(d) {
    for (const e of fs.readdirSync(d, { withFileTypes: true })) {
      const p = path.join(d, e.name);
      if (e.isDirectory()) walk(p);
      else if (e.name.endsWith(".md")) parts.push(fs.readFileSync(p, "utf8"));
    }
  }
  walk(MEM);
  return parts;
}

function needles(m) {
  const text = [m.title, m.content, m.evidence, ...(m.files || [])].join("\n");
  const raw = text.match(/[\u4e00-\u9fffA-Za-z0-9_./:-]{12,}/g) || [];
  const uniq = [...new Set(raw)].filter((s) => !/^https?:\/\//.test(s));
  uniq.sort((a, b) => b.length - a.length);
  return uniq.slice(0, 8);
}

function covered(m, bodies) {
  const nd = needles(m);
  for (const body of bodies) {
    let hits = 0;
    for (const n of nd) {
      if (n.length >= 12 && body.includes(n)) hits++;
      if (hits >= 2) return { ok: true, via: n };
    }
    const long = nd.find((n) => n.length >= 20 && body.includes(n));
    if (long) return { ok: true, via: long };
  }
  return { ok: false };
}

const bodies = allBodies();
const report = JSON.parse(fs.readFileSync(REPORT, "utf8"));
const log = [];

for (const p of report.projects) {
  if (!p.missingTitles?.length) continue;
  const donePath = path.join(process.env.TEMP, `done-${p.project}.json`);
  const set = new Set(fs.existsSync(donePath) ? JSON.parse(fs.readFileSync(donePath, "utf8")) : []);
  for (const title of [...p.missingTitles]) {
    const m = loadMem(p.project, title);
    if (!m) continue;
    const c = covered(m, bodies);
    if (c.ok) {
      set.add(title);
      log.push({ project: p.project, title, via: c.via });
      console.log("MARK", p.project, title.slice(0, 50), "←", c.via?.slice(0, 40));
    } else {
      console.log("STILL MISSING", p.project, title.slice(0, 50));
    }
  }
  fs.writeFileSync(donePath, JSON.stringify([...set], null, 1), "utf8");
}

fs.writeFileSync(path.join(BASE, "out", "mark-done-covered.json"), JSON.stringify({ at: new Date().toISOString(), log }, null, 2));

const align = spawnSync(process.execPath, [path.join(BASE, "scripts", "align-check.mjs")], { cwd: BASE, stdio: "inherit" });
if (align.status === 0) {
  spawnSync(
    process.execPath,
    ["D:\\repository\\skills\\scripts\\snapshot-openviking-memory.mjs", "--commit", "--push", "--reason", "align-final"],
    { cwd: "D:\\repository\\skills", stdio: "inherit" }
  );
}
process.exit(align.status ?? 1);

