const fs=require('fs'),p=require('path'),os=require('os');
const MEM=p.join(os.homedir(),'.openviking/data/viking/default/user/default/memories');
const cats={}; let dot=0, overview=0, foreign=0, total=0;
const BAD=/padrão|estrutura de|projeto de|notas técnicas/i;
function w(d,rel=''){ for(const e of fs.readdirSync(d,{withFileTypes:true})){ const r=rel?rel+'/'+e.name:e.name; const x=p.join(d,e.name); if(e.isDirectory()){ const top=r.split('/')[0]||r; cats[top]=(cats[top]||0); w(x,r);} else if(e.name.endsWith('.md')){ total++; if(e.name.startsWith('.')) dot++; if(e.name==='.overview.md'||/^# Entities Overview/m.test(fs.readFileSync(x,'utf8').slice(0,80))) overview++; if(BAD.test(r)) foreign++; if(!rel.startsWith('.')){ const cat=r.split('/')[0]; cats[cat]=(cats[cat]||0)+1; }}}}
w(MEM);
console.log('total md',total,'dot-prefixed',dot,'overview-like',overview,'foreign-path',foreign);
console.log('top-level',Object.entries(cats).sort((a,b)=>b[1]-a[1]).slice(0,8));
const SRC=p.join(process.env.USERPROFILE,'Documents/deepseek-harness/default-workspace/memory-migration/out/distilled-projects');
let proj=0, entries=0, uniq=new Set();
if(fs.existsSync(SRC)){ for(const d of fs.readdirSync(SRC)){ if(!fs.statSync(p.join(SRC,d)).isDirectory()) continue; proj++; for(const f of fs.readdirSync(p.join(SRC,d)).filter(x=>x.endsWith('.json'))){ for(const m of JSON.parse(fs.readFileSync(p.join(SRC,d,f),'utf8')).memories||[]){ entries++; uniq.add(d+'::'+m.title); }}}}
console.log('distilled projects',proj,'entries',entries,'unique',uniq.size);
"

